import sqlite3
import pandas as pd

# Database paths
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

# Connect to databases
def get_connection(db_name):
    return sqlite3.connect(sqlite_paths[db_name])

try:
    # Create connections
    conn_business = get_connection("business")
    conn_review = get_connection("review")
    conn_user = get_connection("user")

    # Since SQLite doesn't support cross-database joins directly,
    # we'll need to read the necessary data into DataFrames and merge them

    # Read business data for Sparks
    business_query = "SELECT business_id FROM business WHERE city = 'Sparks'"
    df_business = pd.read_sql_query(business_query, conn_business)

    if df_business.empty:
        print("No businesses found in Sparks.")
    else:
        # Get all review records for businesses in Sparks
        business_ids = tuple(df_business['business_id'].tolist())
        if len(business_ids) == 1:
            business_ids = f"('{business_ids[0]}')"
        else:
            business_ids = str(business_ids)

        review_query = f"SELECT user_id FROM review WHERE business_id IN {business_ids}"
        df_reviews = pd.read_sql_query(review_query, conn_review)

        if df_reviews.empty:
            print("No reviews found for businesses in Sparks.")
        else:
            # Get unique user IDs who reviewed businesses in Sparks
            user_ids = tuple(df_reviews['user_id'].unique())
            if len(user_ids) == 1:
                user_ids = f"('{user_ids[0]}')"
            else:
                user_ids = str(user_ids)

            # Get user details for those who have more than 120 reviews
            user_query = f"SELECT name, review_count, average_stars FROM user WHERE user_id IN {user_ids} AND review_count > 120"
            df_users = pd.read_sql_query(user_query, conn_user)

            if df_users.empty:
                print("No users with more than 120 reviews found who reviewed businesses in Sparks.")
            else:
                # Display results
                print("Users in Sparks with more than 120 reviews:")
                print(df_users.to_string(index=False))

except Exception as e:
    print(f"An error occurred: {e}")

finally:
    # Close connections
    if 'conn_business' in locals():
        conn_business.close()
    if 'conn_review' in locals():
        conn_review.close()
    if 'conn_user' in locals():
        conn_user.close()
